const body = $json.body ?? $json;

const contractVersion = body.contractVersion ?? 'legacy';
const requestId = body.requestId ?? `REQ-${Date.now()}`;
const projectId = body.projectId ?? null;
const projectName = body.projectName ?? 'Proyecto';
const documentationText = String(body.documentationText ?? '').trim();
const baseStoriesText = String(body.baseStoriesText ?? '').trim();
const codeContext = Array.isArray(body.codeContext) ? body.codeContext : [];
const apiResources = Array.isArray(body.apiResources) ? body.apiResources : [];

if (!documentationText && !baseStoriesText && codeContext.length === 0) {
  throw new Error('No hay contexto suficiente para generar historias de usuario.');
}

return [{
  json: {
    contractVersion,
    requestId,
    projectId,
    projectName,
    documentationText,
    baseStoriesText,
    codeContext,
    ...(apiResources.length ? { apiResources } : {})
  }
}];

function safeParse(value) {
  if (typeof value !== 'string') return null;
  try { return JSON.parse(value); } catch { return null; }
}

function trimStr(v) {
  return String(v ?? '').trim();
}

const raw = $json.text ?? $json.response ?? $json.output ?? JSON.stringify($json);
const parsed = typeof raw === 'string' ? safeParse(raw) : raw;

if (!parsed || typeof parsed !== 'object') {
  throw new Error('El modelo no devolvió JSON válido.');
}
if (!Array.isArray(parsed.stories)) {
  throw new Error('El JSON no contiene stories[].');
}

const stories = parsed.stories
  .filter((s) => s && typeof s === 'object')
  .map((s) => {
    const moduleName = trimStr(s.module) || 'General';
    const screens = trimStr(s.screensInvolved) || 'N/A';
    const detail = {
      actor: trimStr(s.actor),
      functionalFlow: trimStr(s.functionalFlow),
      screensInvolved: screens,
      businessRules: trimStr(s.businessRules),
      technicalNotes: trimStr(s.technicalNotes),
    };
    return {
      title: trimStr(s.title),
      description: trimStr(s.description),
      module: moduleName,
      criteria: Array.isArray(s.criteria) ? s.criteria.map((c) => trimStr(c)).filter(Boolean) : [],
      status: 'generated',
      detail,
    };
  })
  .filter((s) => s.title.length > 0);

if (stories.length === 0) {
  throw new Error('No se pudieron normalizar historias de usuario.');
}

function deriveModulesFromStories(list) {
  const seen = [];
  const keySet = new Set();
  for (const s of list) {
    const name = s.module || 'General';
    if (!keySet.has(name)) {
      keySet.add(name);
      seen.push(name);
    }
  }
  return seen.map((name, i) => ({ name, order: i + 1, summary: '' }));
}

let modules = [];
if (Array.isArray(parsed.modules) && parsed.modules.length > 0) {
  modules = parsed.modules
    .filter((m) => m && typeof m === 'object')
    .map((m, i) => ({
      name: trimStr(m.name) || `Módulo ${i + 1}`,
      order: Number.isFinite(m.order) ? Number(m.order) : i + 1,
      summary: trimStr(m.summary),
    }))
    .filter((m) => m.name.length > 0);
}
if (modules.length === 0) {
  modules = deriveModulesFromStories(stories);
}

return [{
  json: {
    runId: String(parsed.runId ?? `RUN-${Date.now()}`),
    requestId: String(parsed.requestId ?? ''),
    projectId: parsed.projectId ?? null,
    modules,
    stories,
  },
}];
